#define EPS 1e-9
#define PI acos(-1.0)
#define INF 0x3f3f3f3f
#define LL long long

const int MOD = 1E9+7;
const int N = 1000+5;
const int dx[] = {-1,1,0,0,-1,-1,1,1};
const int dy[] = {0,0,-1,1,-1,1,-1,1};

using namespace std;

LL a[10000];

int main() {
    int n;
    cin >> n; // using cin for faster input
    for(int i=1; i<=n; i++) {
        cin >> a[i]; // using cin for faster input
    }
    LL ans = 0;
    while(true) {
        LL maxn = a[1];
        int id = 1;
        for(int i = 2; i <= n; i++) {
            if(a[i] > maxn) {
                maxn = a[i];
                id = i;
            }
        }
        if(maxn <= n-1)
            break;
        for(int i = 1; i <= n; i++) {
            a[i] += (i == id) ? (maxn % n) - a[i] : maxn / n; // optimize assignments using conditional operator
        }
        ans += maxn / n;
    }
    cout << ans << endl; // using cout for faster output
}

